Section Walk.
  Variable R : art_layout.
  #[local] Hint Extern 0 heap_layout => exact (arl_L R) : typeclass_instances.   (* [comment removed for export] *)
  Variable HIA : artA asegs R.
  Local Notation AL := (arl_AL R).
  Local Notation L := (arl_L R).
  Hypothesis IMG : asan_img_ok AL.
  Local Instance lxi : LxImg asegs AL := lxA_img AL IMG.
  Hypothesis AMS : arl_amemset R = A_ASAN_MEMSET_MM.
  Hypothesis NEED0 : 0 <= arl_need_amem R.
  Variables (h : HST asegs R HIA) (LB LF : list blk).
  Local Notation CS := (hcs asegs R HIA h).
  Variables (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word)
            (F : bvmap 5 word) (fc : bv 32) (m : mem)
            (X A B bn N an T lx la lb ln lt lo : Z) (xs0 ys zs ns ts0 : list word) (wmm wbd : word).
  Hypothesis Han : 1 <= an <= 4999.
  Hypothesis Hbn : 1 <= bn <= 10000.
  Hypothesis Ln : an <= lx /\ an <= la /\ bn <= lb /\ an <= ln /\ 2 * an + 1 <= lt.
  Hypothesis L0 : Z.of_nat (length xs0) = lx.
  Hypothesis LA : Z.of_nat (length ys) = la.
  Hypothesis LB' : Z.of_nat (length zs) = lb.
  Hypothesis LN : Z.of_nat (length ns) = ln.
  Hypothesis LT0 : Z.of_nat (length ts0) = lt.
  Hypothesis DXT : X + 4 * lx <= T \/ T + 4 * lt <= X.
  Hypothesis DAT : locked (A + 4 * la <= T \/ T + 4 * lt <= A).
  Hypothesis DBT : locked (B + 4 * lb <= T \/ T + 4 * lt <= B).
  Hypothesis DNT : locked (N + 4 * ln <= T \/ T + 4 * lt <= N).
  Hypothesis DNX : locked (N + 4 * ln <= X \/ X + 4 * lx <= N).
  Hypothesis ALX : X mod 4 = 0. Hypothesis ALA : A mod 4 = 0. Hypothesis ALB : B mod 4 = 0.
  Hypothesis ALN : N mod 4 = 0. Hypothesis ALT : T mod 4 = 0.
  Hypothesis XB : 0 < X /\ X + 4 * lx < 2^64.
  Hypothesis AB : 0 < A /\ A + 4 * la < 2^64.
  Hypothesis BB : 0 < B /\ B + 4 * lb < 2^64.
  Hypothesis NB : 0 < N /\ N + 4 * ln < 2^64.
  Hypothesis TB : 0 < T /\ T + 4 * lt < 2^64.
  Hypothesis SPR : 0 <= bv_unsigned sp < 2^64.
  Hypothesis SPA : bv_unsigned sp mod 16 = 0.
  Hypothesis LOS : arl_stklo R <= lo.
  Hypothesis LO : lo <= bv_unsigned sp - 208 - arl_need_amem R.
  Hypothesis TOP : bv_unsigned sp <= htop asegs R HIA h.
  Hypothesis SX : X + 4 * lx <= lo \/ bv_unsigned sp <= X.
  Hypothesis SA : locked (A + 4 * la <= lo \/ bv_unsigned sp <= A).
  Hypothesis SBB : locked (B + 4 * lb <= lo \/ bv_unsigned sp <= B).
  Hypothesis SN : locked (N + 4 * ln <= lo \/ bv_unsigned sp <= N).
  Hypothesis STT : T + 4 * lt <= lo \/ bv_unsigned sp <= T.
  Hypothesis RA : bv_unsigned ra mod 2 = 0.
  Hypothesis CWX : client_wrange L (LB ++ fdata LF) (arl_stklo R) (htop asegs R HIA h) X (4 * an).
  Hypothesis CWT : client_wrange L (LB ++ fdata LF) (arl_stklo R) (htop asegs R HIA h) T (4 * (2 * an + 1)).
  Hypothesis HX0 : u32arr asegs m X xs0.
  Hypothesis HA0 : bytes_at asegs m A (u32s ys).
  Hypothesis HB0 : bytes_at asegs m B (u32s zs).
  Hypothesis HN0 : bytes_at asegs m N (u32s ns).
  Hypothesis EBD : wbd = Z_to_bv 64 (Z.land B 7 + 3).

  Ltac rt_facts :=
    pose proof (hcs_ok asegs R HIA h) as CSOK;
    pose proof (cs_ok_sb _ _ CSOK) as SB64;
    pose proof (art_alwf asegs R HIA) as ALWF'; unfold al_wf in ALWF';
    pose proof IMG as IMG'; unfold asan_img_ok in IMG';
    pose proof (art_lo asegs R HIA) as ALO;
    pose proof alloc_ceiling_pos as ACP;
    pose proof (hcs_stack asegs R HIA h) as SCS0;
    match goal with HH : HM _ _ _ h LB LF _ |- _ =>
      pose proof (hm_top asegs R HIA h LB LF _ HH) as HTOP;
      assert (LO0 : 0 <= lo) by (clear - LOS ALO ACP; lia);
      assert (SCS : crange CS lo (bv_unsigned sp - lo)) by (eapply crange_sub; [exact SCS0| clear - LOS; lia| clear - TOP HTOP; lia])
    end.

  Notation POST := (mpi_core_montmul_postA asegs R HIA h LB LF ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc X an T xs0 ts0 lo m).
  (* [comment removed for export] *)
  Notation W1 := [(T, T + 4 * (2 * an + 1)); (lo, bv_unsigned sp)].
  Notation W := [(X, X + 4 * an); (T, T + 4 * (2 * an + 1)); (lo, bv_unsigned sp)].
  Notation SP' := (Z_to_bv 64 (bv_unsigned sp + -144)).
  Notation SB := (Z_to_bv 64 (al_sb AL)).
  Notation SHB := (Z_to_bv 64 (Z.shiftr B 3 + al_sb AL)).
  Notation FRAME mm := (rw_cells asegs mm (bv_unsigned sp + -144)
     [C8 wbd; C8 (Z_to_bv 64 (4 * an)); C8 (Z_to_bv 64 X); C8 (Z_to_bv 64 bn); C8 wmm;
      C8 s11; C8 s10; C8 s9; C8 s8; C8 s7; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra]).
  Notation OBJS mm := (aobj asegs AL CS mm X (4 * an) /\ aobj asegs AL CS mm A (4 * an) /\ aobj asegs AL CS mm B (4 * bn)
                       /\ aobj asegs AL CS mm N (4 * an) /\ aobj asegs AL CS mm T (4 * (2 * an + 1))).
  (* [comment removed for export] *)
  Notation TT := (skipn (Z.to_nat (2 * an + 1)) ts0).
  Notation TINV WW mm ts := (u32arr asegs mm T ts /\ Z.of_nat (length ts) = 2 * an + 1 /\ u32arr asegs mm (T + 4 * (2 * an + 1)) TT
                          /\ munch WW m mm /\ wmono asegs m mm /\ mem_inv asegs mm /\ stk asegs mm lo (bv_unsigned sp + -144)
                          /\ HM asegs R HIA h LB LF mm /\ OBJS mm).
  Notation SUMS := [SUM_amemsetWA 4 5; SUM_mlawA 4].   (* [comment removed for export] *)

  Lemma sub_W1_W : sub_fp W1 W.
  Proof. intros x Hx. cbn [outside] in *. clear -Hx. tauto. Qed.

